package com.meterflow.payments;
import com.meterflow.invoicing.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import java.util.*;
@RestController @RequestMapping("/api/payments/mock")public class PaymentController{private final InvoiceRepository invoices;private final DunningService dunning;private final com.meterflow.notifications.WebhookDeliveryService webhooks;public PaymentController(InvoiceRepository r,DunningService d,com.meterflow.notifications.WebhookDeliveryService w){invoices=r;dunning=d;webhooks=w;}
@PreAuthorize("hasAnyRole('ADMIN','CUSTOMER')")@PostMapping("/{invoiceId}/pay")public Map<String,Object> pay(@PathVariable UUID invoiceId,Authentication auth){var i=invoices.findById(invoiceId).orElseThrow();guard(i.getCustomerId(),auth);if(!i.getStatus().equals("FINALISED"))throw new IllegalArgumentException("Only finalised invoices can be paid");dunning.recordSuccessIfPresent(invoiceId);return Map.of("invoiceId",invoiceId,"paymentStatus","SUCCEEDED","provider","MOCK","message","Mock payment accepted");}
@PreAuthorize("hasAnyRole('ADMIN','CUSTOMER')")@PostMapping("/{invoiceId}/fail")public Map<String,Object> fail(@PathVariable UUID invoiceId,Authentication auth){var i=invoices.findById(invoiceId).orElseThrow();guard(i.getCustomerId(),auth);var c=dunning.recordFailure(invoiceId);webhooks.publish(i.getCustomerId(),"payment.failed",Map.of("invoiceId",invoiceId.toString(),"dunningCaseId",c.getId().toString(),"nextAttemptAt",c.getNextAttemptAt().toString()));return Map.of("invoiceId",invoiceId,"paymentStatus","FAILED","dunningCaseId",c.getId());}
private void guard(String c,Authentication a){if(a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_ADMIN"))&&!a.getName().equals(c))throw new org.springframework.security.access.AccessDeniedException("Customers may only pay their own invoices");}}
